package cn.safetyledger.app.security;
import java.security.SecureRandom;import java.util.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;
public final class PasswordHash{private PasswordHash(){}public static String create(char[]p)throws Exception{byte[]s=new byte[16];new SecureRandom().nextBytes(s);return Base64.getEncoder().encodeToString(s)+":"+Base64.getEncoder().encodeToString(derive(p,s));}public static boolean verify(char[]p,String saved)throws Exception{if(saved==null||!saved.contains(":"))return false;String[]a=saved.split(":",2);byte[]s=Base64.getDecoder().decode(a[0]),want=Base64.getDecoder().decode(a[1]),got=derive(p,s);return java.security.MessageDigest.isEqual(want,got);}private static byte[]derive(char[]p,byte[]s)throws Exception{PBEKeySpec k=new PBEKeySpec(p,s,210000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(k).getEncoded();}finally{k.clearPassword();Arrays.fill(p,'\0');}}}
